import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// spec: specs/hal-engine-tool-input-validation/spec.md#4
it('executes valid static tool input unchanged', async () => {
  const registry = new ToolRegistry();
  const execute = jest.fn(async () => 'forecast');
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    execute
  );
  const input = {location: 'Berlin', units: 'celsius'};

  await expect(registry.execute('weather', input)).resolves.toEqual({result: 'forecast'});
  expect(execute).toHaveBeenCalledTimes(1);
  expect(execute).toHaveBeenCalledWith(input, undefined);
  expect(input).toEqual({location: 'Berlin', units: 'celsius'});
});
EOF
